import {escapeHtml as esc} from './components.js';
import {updated,safeLink} from './research-view.js';
export const labels={revenue:'매출',operatingIncome:'영업이익',netIncome:'순이익',operatingCashFlow:'영업현금흐름',capex:'설비투자',freeCashFlow:'잉여현금흐름 (FCF)',eps:'희석 EPS',operatingMargin:'영업이익률',freeCashFlowMargin:'FCF 마진'};
const fmt=(n,digits=2)=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:digits}):'—';
const span=p=>(Date.parse(p.end)-Date.parse(p.start))/86400000+1;
export function comparison(p,previous,key){
 if(!p||!previous||p.unit!==previous.unit||p.tag!==previous.tag||p.basis!==previous.basis||Math.abs(span(p)-span(previous))>14)return {text:'비교 자료 없음',pct:null};
 const gap=(Date.parse(p.end)-Date.parse(previous.end))/86400000;
 if(gap<330||gap>400)return {text:'비교 자료 없음',pct:null};
 const a=p.value,b=previous.value;if(!Number.isFinite(a)||!Number.isFinite(b))return {text:'비교 자료 없음',pct:null};
 if(p.unit==='%')return {text:(a-b>0?'+':'')+fmt(a-b)+'%p',pct:null};
 const profit=['operatingIncome','netIncome','eps'].includes(key);
 if(a===b)return {text:'변동 없음',pct:b>0?0:null};
 if(b<=0||a<0){
  if(b===0)return {text:'전년 0 · 증감률 산출 안 함',pct:null};
  if(b<0&&a>0)return {text:profit?'흑자 전환':'음수 → 양수',pct:null};
  if(b>0&&a<0)return {text:profit?'적자 전환':'양수 → 음수',pct:null};
  if(b<0&&a===0)return {text:profit?'손익분기':'0으로 전환',pct:null};
  return {text:profit?(a>b?'적자 축소':'적자 확대'):(a>b?'음수 규모 축소':'음수 규모 확대'),pct:null};
 }
 const pct=(a/b-1)*100;return {text:(pct>0?'+':'')+fmt(pct)+'%',pct};
}
export function previousPoint(rows,row,key){const p=row?.values[key];return p?rows.filter(r=>r.end<row.end).map(r=>r.values[key]).filter(Boolean).find(old=>Math.abs((Date.parse(p.end)-Date.parse(old.end))/86400000-365)<=25):null;}
export function withMargins(rows){return rows.map(row=>{const values={...row.values};for(const [key,profit] of [['operatingMargin','operatingIncome'],['freeCashFlowMargin','freeCashFlow']]){const a=values[profit],r=values.revenue;if(Number.isFinite(r?.value)&&r.value>0&&Number.isFinite(a?.value)&&a.basis===r.basis&&a.unit===r.unit&&a.start===r.start&&a.end===r.end&&a.accession===r.accession)values[key]={...a,value:a.value/r.value*100,unit:'%',tag:key,formula:labels[profit]+' ÷ 매출 × 100',inputs:[a,r]};}return {...row,values};});}
export function selectPeriods(rows,years){if(years==='all'||!rows.length)return rows;const end=rows.at(-1).end,cut=new Date(end+'T00:00:00Z');cut.setUTCFullYear(cut.getUTCFullYear()-Number(years));return rows.filter(r=>r.end>cut.toISOString().slice(0,10));}
function unitScale(rows,key,currency){const max=Math.max(0,...rows.map(r=>Math.abs(r.values[key]?.value||0)));if(key==='eps')return {n:1,label:currency+'/주'};if(key.endsWith('Margin'))return {n:1,label:'%'};return currency==='KRW'&&max>=1e12?{n:1e12,label:'조 원'}:currency==='KRW'&&max>=1e8?{n:1e8,label:'억 원'}:max>=1e9?{n:1e9,label:'십억 '+currency}:max>=1e6?{n:1e6,label:'백만 '+currency}:{n:1,label:currency};}
export function mountFinancialDashboard(root,{onInterval}){
 let data={},loading=false,interval='annual',years='5',group='cash',selected=new Set(['revenue','operatingIncome','freeCashFlow','freeCashFlowMargin','eps']),page=0;const abort=new AbortController(),signal=abort.signal,points=new Map();
 const choices={growth:['revenue','operatingIncome','netIncome','operatingMargin'],cash:['freeCashFlow','freeCashFlowMargin','operatingCashFlow','capex'],share:['eps']};
 const exact=p=>fmt(p?.value,20)+' '+(p?.unit||'');
 const provenance=p=>p?`<details class="financial-provenance"><summary>원본·계산 근거</summary><p>${p.startDerived?esc(p.end)+' 종료 · 시작일 미제공':esc(p.start)+' ~ '+esc(p.end)} · ${esc(p.source)} · ${esc(p.form||'')} · 공시 ${esc(p.filedAt||'확인 불가')} · ${esc(p.tag)}</p>${p.formula?`<p>${esc(p.formula)}${p.inputs?.length?' · 원본 값 '+p.inputs.map(i=>fmt(i.value)+' '+(i.unit||p.unit)).map(esc).join(' / '):''}</p>`:''}<a target="_blank" rel="noopener noreferrer" href="${safeLink(p.url)}">${esc(p.sourceUrlLabel||'원본 공시')} ↗</a></details>`:'';
 function chart(key,rows,all){
  const scale=unitScale(rows,key,data.currency||'USD'),vals=rows.map(r=>r.values[key]?.value).filter(Number.isFinite),max=Math.max(0,...vals),min=Math.min(0,...vals),height=170,width=600,left=76,right=16,zero=26+(max/(max-min||1))*height,y=v=>26+(max-v)/(max-min||1)*height,step=(width-left-right)/Math.max(rows.length,1);
  return `<article class="financial-chart"><h3>${labels[key]} <small>${esc(scale.label)}</small></h3>${!vals.length?'<p class="research-empty">조회 가능한 값이 없습니다.</p>':`<svg viewBox="0 0 600 245" role="group" aria-label="${labels[key]} 추이"><line x1="${left}" x2="584" y1="${zero}" y2="${zero}" class="financial-zero"/>${[...new Set([min,max,0])].map(v=>`<text x="68" y="${y(v)+4}" text-anchor="end">${esc((v/scale.n).toLocaleString('ko-KR',{maximumFractionDigits:1}))}</text>`).join('')}${rows.map((r,i)=>{const p=r.values[key],id=key+':'+r.end,change=comparison(p,previousPoint(all,r,key),key),x=left+step*(i+.15),w=step*.7,label=interval==='annual'?r.label:r.end.slice(2,7);if(p)points.set(id,{p,label:r.label,key,change});return `<g${p?` tabindex="0" role="button" data-financial-point="${id}" aria-label="${esc(r.label+' '+exact(p)+' 전년 동기 대비 '+change.text)}"`:''}>${p?`<title>${esc(r.label+' · '+exact(p)+' · 전년 동기 대비 '+change.text)}</title><rect x="${x}" width="${w}" y="${Math.min(zero,y(p.value))}" height="${Math.max(1,Math.abs(zero-y(p.value)))}" fill="${p.value<0?'#5287c5':'#148b80'}" rx="2"/><rect x="${left+step*i}" y="20" width="${step}" height="184" fill="transparent"/>`:`<text x="${x+w/2}" y="${zero-5}" text-anchor="middle">—</text>`}${(i%Math.max(1,Math.ceil(rows.length/6))===0||i===rows.length-1)?`<text x="${x+w/2}" y="222" text-anchor="middle">${esc(label)}</text>`:''}</g>`;}).join('')}</svg><div class="financial-point-label" data-point-label="${key}" role="status">막대에 마우스를 올리거나 눌러 정확한 값 확인</div>`}</article>`;
 }
 function render(){
  points.clear();const all=withMargins(data[interval==='annual'?'annual':'quarterly']||[]),rows=selectPeriods(all,years),last=all.at(-1),keys=['revenue','operatingIncome','netIncome','operatingCashFlow','capex','freeCashFlow','freeCashFlowMargin','eps'];page=Math.min(page,Math.max(0,Math.ceil(rows.length/5)-1));const tableRows=rows.slice().reverse().slice(page*5,page*5+5);
  const amount=(p,k)=>{if(!p)return '—';const s=unitScale(all,k,data.currency||'USD');return fmt(p.value/s.n)+' '+s.label;};
  root.innerHTML=`<div class="research-heading"><div><h2>재무정보</h2><p>${esc(data.basisLabel||'확정 공시 기준')} · ${esc(data.currency||'통화 확인 중')} · TTM 제외</p></div><div class="financial-controls"><label>회계기간 <select data-financial-interval aria-label="재무 회계기간"><option value="annual">연간</option><option value="quarter">분기</option></select></label><label>조회 범위 <select data-financial-years aria-label="재무 조회 범위"><option value="3">3년</option><option value="5">5년</option><option value="all">전체</option></select></label></div></div>${loading?'<p role="status">공시 재무를 확인하고 있어요. 저장된 자료가 있으면 먼저 표시합니다.</p>':''}<div class="financial-summary-grid">${['freeCashFlow','freeCashFlowMargin','revenue','operatingIncome'].map(k=>{const p=last?.values[k],change=comparison(p,previousPoint(all,last,k),k);return `<article><span>${labels[k]}</span><strong title="${esc(exact(p))}">${esc(amount(p,k))}</strong><small>전년 동기 대비 ${esc(change.text)}</small><small>${esc(last?.label||'기간 확인 불가')}${last?' · '+esc(last.end)+' 종료':''}</small></article>`;}).join('')}</div><p class="financial-fact">${last?esc(last.label+' · 영업현금흐름 '+amount(last.values.operatingCashFlow,'operatingCashFlow')+' · 설비투자 '+amount(last.values.capex,'capex')):esc(data.message||'확인된 공시 재무가 없습니다.')}</p><div class="research-filters financial-groups" role="group" aria-label="재무 차트 종류">${[['growth','성장·수익성'],['cash','현금흐름·FCF'],['share','주당지표']].map(([v,l])=>`<button data-financial-group="${v}" aria-pressed="${group===v}">${l}</button>`).join('')}</div>${group==='cash'?`<p class="financial-fact">${esc(data.fcfDefinition||'FCF = 영업현금흐름 − 유형자산 취득 현금지출')} · FCF 마진 = FCF ÷ 매출 × 100</p>`:''}<div class="financial-metric-choices">${choices[group].map(k=>`<label><input type="checkbox" data-financial-metric="${k}" ${selected.has(k)?'checked':''}>${labels[k]}</label>`).join('')}</div><div class="financial-chart-grid">${choices[group].filter(k=>selected.has(k)).map(k=>chart(k,rows,all)).join('')||'<p class="research-empty">확인할 항목을 선택해 주세요.</p>'}</div><div class="research-heading financial-table-heading"><h3>상세 수치</h3><p>${rows.length}개 기간${rows.length?' · '+esc(rows[0].end)+' ~ '+esc(rows.at(-1).end):''} · 단위는 행별 표시</p></div><table class="financial-detail-table"><thead><tr><th scope="col">항목 · 단위</th>${tableRows.map(r=>`<th scope="col">${esc(r.label)}<small>${esc(r.end)} 종료</small></th>`).join('')}</tr></thead><tbody>${keys.map(k=>{const scale=unitScale(all,k,data.currency||'USD');return `<tr><th scope="row">${labels[k]}<small>${esc(scale.label)}</small></th>${tableRows.map(r=>{const p=r.values[k];return `<td data-label="${esc(r.label)}" title="${esc(p?exact(p):'데이터 없음')}">${p?`<button data-financial-value="${k}:${r.end}">${esc(fmt(p.value/scale.n))}</button>`:'—'}</td>`;}).join('')}</tr>`;}).join('')}</tbody></table>${rows.length>5?`<div class="financial-table-pages"><button data-financial-page="-1" ${page===0?'disabled':''}>최근 기간</button><span>${page+1} / ${Math.ceil(rows.length/5)} · 선택 범위 내 5개 기간씩</span><button data-financial-page="1" ${page+1>=Math.ceil(rows.length/5)?'disabled':''}>이전 기간</button></div>`:''}<div class="financial-table-inspect" role="status"></div><footer class="financial-footnote"><p>${esc(data.source||'공시 자료')} · 갱신 ${esc(updated(data.updatedAt))}${data.stale?' · 갱신 지연, 마지막 저장값':''}</p><p>${interval==='quarter'?'분기 단독 실적만 표시합니다. ':''}확보한 기간만 표시하며 결측치는 —입니다. ${esc((data.limitations||[]).join(' · '))}</p>${data.ratios?.length?`<details><summary>공시·시세 기준 가치평가 및 건전성</summary><dl class="company-information">${data.ratios.map(r=>`<div><dt>${esc(r.label)}</dt><dd>${esc(r.display||fmt(r.value)+r.unit)}<small>${esc(r.basis)} · ${esc(r.formula)}</small>${r.sourceUrl?`<a href="${safeLink(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">원본 공시 ↗</a>`:''}</dd></div>`).join('')}</dl></details>`:''}${data.finvizSnapshot?`<details><summary>Finviz 현재 재무 지표 · 과거 실적과 구분</summary><p>조회 ${esc(updated(data.finvizSnapshot.updatedAt))}${data.finvizSnapshot.stale?' · 갱신 지연, 마지막 저장값':''} · 공시 회계기간 미제공</p><dl class="company-information">${(data.finvizSnapshot.metrics||[]).filter(m=>m.field!=='Profit Margin').map(m=>`<div><dt>${esc(m.label)}</dt><dd>${esc(fmt(m.value))}${esc(m.unit)}</dd></div>`).join('')}</dl><p>${esc(data.finvizSnapshot.message||'')}</p></details>`:''}<details><summary>비교·계산 기준</summary><p>전년 동일 회계기간·단위·계정만 비교합니다. 전년 값이 0이거나 부호가 바뀌면 일반 증감률을 표시하지 않습니다. 영업이익률과 FCF 마진은 같은 공시·기간·재무 기준의 영업이익 또는 FCF ÷ 매출 × 100이며 별도 축에 표시합니다. 매출이 0 이하이거나 비교 자료가 없으면 비율을 계산하지 않습니다.</p></details></footer>`;
  root.querySelector('[data-financial-interval]').value=interval;root.querySelector('[data-financial-years]').value=years;
 }
 function inspect(id,table=false){let point=points.get(id);if(!point){const [key,end]=id.split(':'),all=withMargins(data[interval==='annual'?'annual':'quarterly']||[]),r=all.find(r=>r.end===end);if(r?.values[key])point={p:r.values[key],key,label:r.label,change:comparison(r.values[key],previousPoint(all,r,key),key)};}if(!point)return;const el=root.querySelector(table?'.financial-table-inspect':'[data-point-label="'+point.key+'"]');if(el)el.innerHTML=`<strong>${esc(point.label)} · ${labels[point.key]} ${esc(exact(point.p))}</strong><span>전년 동기 대비 ${esc(point.change.text)}</span>${provenance(point.p)}`;}
 root.addEventListener('change',e=>{if(e.target.matches('[data-financial-interval]')){interval=e.target.value;page=0;render();onInterval(interval);}if(e.target.matches('[data-financial-years]')){years=e.target.value;page=0;render();}if(e.target.dataset.financialMetric){const k=e.target.dataset.financialMetric;e.target.checked?selected.add(k):selected.delete(k);render();}},{signal});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.financialGroup){group=b.dataset.financialGroup;render();}if(b?.dataset.financialPage){page+=Number(b.dataset.financialPage);render();}if(b?.dataset.financialValue)inspect(b.dataset.financialValue,true);const p=e.target.closest('[data-financial-point]');if(p)inspect(p.dataset.financialPoint);},{signal});
 for(const event of ['pointerover','focusin'])root.addEventListener(event,e=>{const p=e.target.closest('[data-financial-point]');if(p)inspect(p.dataset.financialPoint);},{signal});
 root.addEventListener('keydown',e=>{const p=e.target.closest('[data-financial-point]');if(p&&['Enter',' '].includes(e.key)){e.preventDefault();inspect(p.dataset.financialPoint);}},{signal});
 return {set(next,pending=false){data=next||{};loading=pending;render();},destroy(){abort.abort();}};
}
